CREATE OR REPLACE FUNCTION public.agenda_visible(_event uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT public.is_active_member(_uid) AND EXISTS(SELECT 1 FROM public.agenda_events e WHERE e.id=_event AND (public.is_captain(_uid) OR e.team_wide OR e.created_by=_uid OR e.organizer_id=_uid OR e.sector_id=(SELECT m.sector_id FROM public.memberships m WHERE m.user_id=_uid) OR EXISTS(SELECT 1 FROM public.agenda_invitees i WHERE i.event_id=e.id AND i.user_id=_uid) OR EXISTS(SELECT 1 FROM public.memberships manager JOIN public.agenda_invitees i ON i.event_id=e.id JOIN public.memberships invited ON invited.user_id=i.user_id WHERE manager.user_id=_uid AND manager.role='gerente' AND manager.sector_id=invited.sector_id)))
$$;